				let changed = false;
				for (const [oldRel, newRel] of renames) {
					const oldBasename = oldRel.split("/").pop();
					const newBasename = newRel.split("/").pop();
					if (oldBasename !== newBasename && code.includes(oldBasename)) {
						code = code.replaceAll(oldBasename, newBasename);
						changed = true;
					}
				}
